        // no-op
      },
      onData: (value) => {
        values.push(value);
      },
      onError: (error) => {
        reject(error);
      },
      onComplete: () => {
        resolve();
      },
      onStopped: () => {
        resolve();
      },
      onConnectionStateChange: () => {
        // no-op
      },
    });
  });

  await fs.writeFile('/home/user/project/output.json', JSON.stringify(values));
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
